"""DTMF event composition handler."""

from __future__ import annotations

from typing import ClassVar, Optional

import structlog

from rasa.core.channels.conversation_queue.queue import ConversationQueue
from rasa.core.voice.dtmf import ActiveDTMFCollect, ActiveDTMFCollectResolver
from rasa.core.voice.event_composition.events import CompositeEvent, UserDTMFInput
from rasa.core.voice.event_composition.events.input_events import DTMFKeypressInputEvent
from rasa.core.voice.event_composition.handlers.protocol import (
    RawEventTypes,
)
from rasa.tracing import voice as voice_tracing

structlogger = structlog.get_logger()


class DTMFHandler:
    """Compose raw DTMF keypresses into DTMF interaction events."""

    interested_in: ClassVar[RawEventTypes] = [DTMFKeypressInputEvent]

    def __init__(
        self,
        sender_id: str,
        resolve_active_dtmf_collect: ActiveDTMFCollectResolver,
        interaction_event_queue: ConversationQueue[CompositeEvent],
    ) -> None:
        """Create a DTMF handler."""
        self.sender_id = sender_id
        self._resolve_active_dtmf_collect = resolve_active_dtmf_collect
        self.interaction_event_queue = interaction_event_queue
        self._buffer = ""
        self._buffer_field_name: Optional[str] = None

    async def handle(self, event: DTMFKeypressInputEvent) -> None:
        """Handle DTMF raw input."""
        with voice_tracing.handle_dtmf_span() as dtmf_span:
            active_collect = await self._resolve_active_dtmf_collect(self.sender_id)
            if active_collect is None:
                self._clear_buffer()
                dtmf_span.record_ignored()
                return

            if self._buffer_field_name != active_collect.field_name:
                if self._buffer:
                    structlogger.debug(
                        "voice.dtmf.buffer_discarded",
                        previous_field=self._buffer_field_name,
                        field=active_collect.field_name,
                        discarded_count=len(self._buffer),
                    )
                self._clear_buffer()
                self._buffer_field_name = active_collect.field_name

            if not self._buffer:
                dtmf_span.record_started()
            self._buffer += event.digit
            dtmf_span.record_digit(buffered_count=len(self._buffer))

            completed_input = self._completed_input(event.digit, active_collect)
            if completed_input is None:
                return

            self._clear_buffer()
            await self.interaction_event_queue.put(
                UserDTMFInput(
                    text=completed_input,
                    field_name=active_collect.field_name,
                    turn_triggered_at_monotonic=event.created_at_monotonic,
                )
            )
            dtmf_span.record_accepted()

    def _completed_input(
        self,
        digit: str,
        active_collect: ActiveDTMFCollect,
    ) -> Optional[str]:
        """Return completed DTMF input, or `None` if collection should continue."""
        if active_collect.length and len(self._buffer) >= active_collect.length:
            return self._buffer

        if active_collect.finish_on_key and digit == active_collect.finish_on_key:
            return self._buffer[:-1]

        return None

    def handle_timeout(self) -> None:
        """Record a DTMF timeout and clear any partially collected input."""
        if self._buffer:
            voice_tracing.record_dtmf_timeout()
        self._clear_buffer()

    def _clear_buffer(self) -> None:
        self._buffer = ""
        self._buffer_field_name = None
